p = 'D:/GITHUB  Project/Custom WorkFlow/.claude/worktrees/workspace-scan-resume-06b524/sangam/TESTING-GAP-REGISTER.md'
raw = io.open(p, encoding='utf-8', newline='').read()
nl = '\r\n' if '\r\n' in raw else '\n'
lines = raw.split(nl)
idx = [i for i, l in enumerate(lines) if l.startswith('| APPROVE-401 |')]
assert len(idx) == 1
assert not any(l.startswith('| DEC-138 |') for l in lines)
